<div x-cloak x-show="broadcastModalOpen" class="attention-overlay" @keydown.escape.window="broadcastModalOpen = false" @click.self="broadcastModalOpen = false" role="dialog" aria-modal="true" aria-labelledby="broadcast-heading">
    <form class="attention-broadcast" @submit.prevent="sendBroadcast()"><header class="attention-heading"><div><h2 id="broadcast-heading">Broadcast notification</h2><p>Send an announcement to auditees in a department.</p></div><button type="button" class="attention-button" @click="broadcastModalOpen = false" aria-label="Close broadcast">×</button></header><p class="attention-error" x-show="error" x-text="error" role="alert"></p><label>Department<select x-model="broadcastForm.departmentId" required><option value="">Choose a department</option><template x-for="department in departments" :key="department._id"><option :value="department._id" x-text="department.departmentName"></option></template></select></label><label>Message<textarea x-model="broadcastForm.message" required maxlength="2000" rows="5"></textarea></label><div class="attention-actions"><button type="button" class="attention-button" @click="broadcastModalOpen = false">Cancel</button><button type="submit" class="attention-button is-primary" :disabled="saving" x-text="saving ? 'Sending…' : 'Send broadcast'"></button></div></form>
</div>
